def getFactors(n: int) -> list[list[int]]:
    res = []
    def backtrack(rem, start, path):
        if path:
            res.append(path + [rem])
        for f in range(start, int(rem**0.5) + 1):
            if rem % f == 0:
                backtrack(rem // f, f, path + [f])
    backtrack(n, 2, [])
    res.sort()
    return res

